<?php
require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/CardService.php';$svc=new CardService(Database::connection());$uid=(int)auth_user()['id'];$error=null;$success=null;$issued=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='issue'){$issued=$svc->issue($uid,(int)$_POST['account_id'],$_POST['card_type']??'virtual',$_POST['network']??'demo_visa');$success='Card issued. Save the demo card details shown below; the full card number is not stored for later display.';}elseif($action==='status'){$svc->setStatus($uid,(int)$_POST['card_id'],$_POST['status']);$success='Card status updated.';}elseif($action==='pin'){$svc->setPin($uid,(int)$_POST['card_id'],trim($_POST['pin']));$success='Card PIN set.';}elseif($action==='limits'){$svc->setLimits($uid,(int)$_POST['card_id'],trim($_POST['daily_limit']),trim($_POST['per_transaction_limit']));$success='Card limits updated.';}}catch(Throwable $e){$error=$e->getMessage();}}$cards=$svc->list($uid);$stmt=Database::connection()->prepare('SELECT a.id,a.account_number,at.currency,a.available_balance FROM accounts a JOIN account_types at ON at.id=a.account_type_id WHERE a.user_id=? AND a.status="active" ORDER BY a.id');$stmt->execute([$uid]);$accounts=$stmt->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cards - <?=e(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h2>My Cards</h2><a href="/commserve/public/dashboard.php">Dashboard</a></div><div class="alert alert-warning">Simulation only. These card numbers are not real payment credentials and cannot be used on real networks.</div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($issued):?><div class="alert alert-info"><b>Demo card details — save now:</b><br>Number: <code><?=e($issued['pan'])?></code><br>Expiry: <?=e(sprintf('%02d/%d',$issued['expiry_month'],$issued['expiry_year']))?><br>CVV: <code><?=e($issued['cvv'])?></code></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><h5>Issue simulated card</h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="issue"><div class="col-md-4"><label class="form-label">Account</label><select name="account_id" class="form-select" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['account_number'])?> — <?=format_money($a['available_balance'],$a['currency'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Card type</label><select name="card_type" class="form-select"><option value="virtual">Virtual</option><option value="debit">Debit</option></select></div><div class="col-md-3"><label class="form-label">Network</label><select name="network" class="form-select"><option value="demo_visa">Demo Visa</option><option value="demo_mastercard">Demo Mastercard</option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Issue</button></div></form></div></div><div class="row g-3"><?php foreach($cards as $c):?><div class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><h5><?=e(ucwords(str_replace('_',' ',$c['network'])))?></h5><span class="badge text-bg-<?=($c['status']==='active'?'success':'secondary')?>"><?=e($c['status'])?></span></div><div class="fs-4">•••• •••• •••• <?=e($c['last4'])?></div><div class="small text-muted mb-3"><?=e(ucfirst($c['card_type']))?> · Expires <?=e(sprintf('%02d/%d',$c['expiry_month'],$c['expiry_year']))?> · Account <?=e($c['account_number'])?></div><div class="d-flex gap-2 flex-wrap"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="card_id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='active'?'frozen':'active'?>"><button class="btn btn-sm btn-outline-secondary"><?=$c['status']==='active'?'Freeze':'Unfreeze'?></button></form><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="pin"><input type="hidden" name="card_id" value="<?=$c['id']?>"><input name="pin" class="form-control form-control-sm" placeholder="4-6 digit PIN" inputmode="numeric" required><button class="btn btn-sm btn-outline-primary">Set PIN</button></form></div><hr><form method="post" class="row g-2"><?=csrf_field()?><input type="hidden" name="action" value="limits"><input type="hidden" name="card_id" value="<?=$c['id']?>"><div class="col"><input name="daily_limit" class="form-control form-control-sm" value="<?=$c['daily_limit']?>" placeholder="Daily limit"></div><div class="col"><input name="per_transaction_limit" class="form-control form-control-sm" value="<?=$c['per_transaction_limit']?>" placeholder="Per transaction"></div><div class="col-auto"><button class="btn btn-sm btn-outline-dark">Save limits</button></div></form></div></div></div><?php endforeach;?></div></div></body></html>
